insert into public.regimens (id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms)
select id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms
from jsonb_populate_recordset(null::public.regimens, $catalog$[{"id":"begev","short_name":"BeGEV","name":{"uk":"BeGEV (бендамустин, гемцитабін, вінорельбін, преднізолон)","en":"BeGEV (bendamustine, gemcitabine, vinorelbine, prednisolone)"},"description":{"uk":"Рецидив або рефрактерність класичної лімфоми Ходжкіна після однієї лінії, перед аутотрансплантацією. 4 цикли по 21 дню.","en":"Classical Hodgkin lymphoma relapsed or refractory after one line, before an autologous transplant. Four 21-day cycles."},"cycle_length_days":21,"default_cycles":4,"sort_order":0,"sources":[{"name":"Santoro A. та ін. Five-year results of the BEGEV salvage regimen in relapsed/refractory classical Hodgkin lymphoma. Blood Adv. 2020;4:136-140","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6960479/","version":"повний текст у PMC (розклад схеми)","checkedOn":"2026-11-19"},{"name":"Santoro A. та ін. Bendamustine in Combination With Gemcitabine and Vinorelbine Is an Effective Regimen As Induction Chemotherapy Before Autologous Stem-Cell Transplantation for Relapsed or Refractory Hodgkin Lymphoma: Final Results of a Multicenter Phase II Study. J Clin Oncol. 2016;34:3293-3299","url":"https://pubmed.ncbi.nlm.nih.gov/27382096/","version":"резюме; фаза II, 59 пацієнтів","checkedOn":"2026-10-09"},{"name":"ClinicalTrials.gov NCT01884441 (BeGEV), опис груп лікування","url":"https://clinicaltrials.gov/study/NCT01884441","version":"запис на дату звірки","checkedOn":"2026-11-19"}],"evidence":{"design":{"uk":"Багатоцентрове відкрите дослідження фази II без групи порівняння (Італія). Первинна кінцева точка — повна відповідь після 4 циклів.","en":"A multicentre open-label phase II study without a comparison group (Italy). The primary end point was complete response after four cycles."},"population":{"uk":"59 пацієнтів з рецидивом або рефрактерністю після однієї лінії хіміотерапії.","en":"59 patients relapsed or refractory after one chemotherapy line."},"results":{"uk":"Повна відповідь 73–75%, загальна — 83%. Стовбурові клітини зібрано в 55 з 57. П'ятирічна виживаність без прогресування 59%, загальна — 78%; після трансплантації — 77% і 91%, однаково при рецидиві й рефрактерності.","en":"Complete response 73 to 75%, overall 83%. Stem cells were collected in 55 of 57. Five-year progression-free survival 59%, overall 78%; after a transplant 77% and 91%, the same in relapsed and refractory disease."},"conduct":{"uk":"Токсичність 3–4 ступеня: тромбоцитопенія й нейтропенія по 13,5%, фебрильна нейтропенія — 7 пацієнтів. Вторинних лейкозів не було.","en":"Grade 3 to 4 toxicity: thrombocytopenia and neutropenia 13.5% each, febrile neutropenia in 7 patients. No secondary leukaemia."},"trial":{"nct":"NCT01884441","phase":"II","randomized":false,"n":59},"settings":["relapse","refractory","pre-transplant"],"verdict":"option","appraisal":[{"publication":"Santoro A. та ін. J Clin Oncol. 2016;34:3293-3299","pmid":"27382096","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article","Multicenter Study"],"journal":{"name":"Journal of Clinical Oncology","issn":"0732-183X","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/27382096/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Journal of Clinical Oncology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/8309333","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]},{"publication":"Santoro A. та ін. Blood Adv. 2020;4:136-140","pmid":"31935284","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial","Journal Article","Research Support, Non-U.S. Gov't"],"journal":{"name":"Blood Advances","issn":"2473-9529","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/31935284/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Blood Advances» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/101698425","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"dhap","short_name":"DHAP","name":{"uk":"DHAP (дексаметазон, цитарабін, цисплатин)","en":"DHAP (dexamethasone, cytarabine, cisplatin)"},"description":{"uk":"Дексаметазон дні 1–4, цисплатин 100 мг/м² за 24 години день 1, цитарабін 2000 мг/м² двічі (через 12 годин) день 2. Цикл 21 день, 2–6 циклів (eviQ); у первинній публікації — 6–10 курсів кожні 3–4 тижні (Velasquez 1988).","en":"Dexamethasone on days 1-4, cisplatin 100 mg/m2 over 24 hours on day 1, cytarabine 2000 mg/m2 twice (12 hours apart) on day 2. A 21-day cycle, 2 to 6 cycles (eviQ); the original publication gave 6 to 10 courses every 3 to 4 weeks (Velasquez 1988)."},"cycle_length_days":21,"default_cycles":2,"sort_order":0,"sources":[{"name":"eviQ: DHAP (дексаметазон, цитарабін, цисплатин), протокол 833, вер. 4 від 20.03.2024","url":"https://www.eviq.org.au/haematology/lymphoma/833-dhap-dexamethasone-cytarabine-cisplatin","version":"вер. 4 від 20.03.2024","checkedOn":"2026-11-19"},{"name":"Velasquez W.S. та ін. Effective salvage therapy for lymphoma with cisplatin in combination with high-dose Ara-C and dexamethasone (DHAP). Blood. 1988;71:117-122","url":"https://pubmed.ncbi.nlm.nih.gov/3334893/","version":"резюме; 90 пацієнтів з рецидивом лімфоми","checkedOn":"2026-11-19"}],"evidence":null,"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"gvd","short_name":"GVD","name":{"uk":"GVD (гемцитабін, вінорельбін, ліпосомальний доксорубіцин)","en":"GVD (gemcitabine, vinorelbine, liposomal doxorubicin)"},"description":{"uk":"Рецидив класичної лімфоми Ходжкіна, зокрема після аутотрансплантації (тоді дози нижчі — галочка). Цикли 21 день; кількість циклів джерело не наводить.","en":"Relapsed classical Hodgkin lymphoma, including after an autologous transplant (then lower doses, a checkbox). 21-day cycles; the source gives no number of cycles."},"cycle_length_days":21,"default_cycles":null,"sort_order":0,"sources":[{"name":"Bartlett N.L. та ін. Gemcitabine, vinorelbine, and pegylated liposomal doxorubicin (GVD), a salvage regimen in relapsed Hodgkin's lymphoma: CALGB 59804. Ann Oncol. 2007;18:1071-1079","url":"https://pubmed.ncbi.nlm.nih.gov/17426059/","version":"резюме; фаза I–II, 91 пацієнт","checkedOn":"2026-11-19"}],"evidence":{"design":{"uk":"Дослідження фази I–II групи CALGB з підбором дози, окремо для пацієнтів без трансплантації і після неї.","en":"A CALGB phase I to II dose-finding study, separately for patients without and after a transplant."},"population":{"uk":"91 пацієнт з рецидивом лімфоми Ходжкіна.","en":"91 patients with relapsed Hodgkin lymphoma."},"results":{"uk":"Загальна відповідь 70%, повна — 19%. Без трансплантації в анамнезі, з подальшою аутотрансплантацією: чотирирічна безподійна виживаність 52%, загальна — 70%. Після невдалої трансплантації — 10% і 34%.","en":"Overall response 70%, complete 19%. Transplant-naive patients going on to an autologous transplant: four-year event-free survival 52%, overall 70%. After a failed transplant, 10% and 34%."},"conduct":{"uk":"Дозолімітувальна токсичність — мукозит у пацієнтів без трансплантації і фебрильна нейтропенія після неї.","en":"Dose-limiting toxicity was mucositis in transplant-naive patients and febrile neutropenia after a transplant."},"trial":{"acronym":"CALGB 59804","phase":"I-II","randomized":false,"n":91},"settings":["relapse","refractory"],"verdict":"option","appraisal":[{"publication":"Bartlett N.L. та ін. Ann Oncol. 2007;18:1071-1079","pmid":"17426059","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase I","Clinical Trial, Phase II","Journal Article","Research Support, N.I.H., Extramural"],"journal":{"name":"Annals of Oncology","issn":"0923-7534","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/17426059/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Annals of Oncology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/9007735","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}}]$catalog$::jsonb)
